# CP25 Step 3A reconstructed metadata merge and age QC.
rm(list=ls()); source(file.path(Sys.getenv("SDY2583_REPO_ROOT",unset="."),"R","shared","reconstructed_panel_framework.R")); rp_install_and_load(c("dplyr","readr","stringr","tibble","purrr")); source(file.path(sd_repo_root(),"R","panels","CP25","MANIFEST_RECONSTRUCTED.R"))
a<-sd_analysis_dir("CP25"); r<-file.path(a,"11_RData"); out<-file.path(a,"04_metadata_merge"); age<-file.path(a,"05_age_QC"); dir.create(out,recursive=TRUE,showWarnings=FALSE); dir.create(age,recursive=TRUE,showWarnings=FALSE)
load(file.path(r,"SDY2583_CP25_STEP2_feature_extraction_RECONSTRUCTED.RData")); m<-rp_merge_metadata("CP25",feature_table,CP25_MANIFEST$module_map$feature); analysis_data<-m$data; metadata<-m$metadata
summary<-tibble::tibble(n_rows=nrow(analysis_data),n_valid_age=sum(!is.na(analysis_data$age_for_model)),n_healthy=sum(analysis_data$disease_group=="Healthy control",na.rm=TRUE),n_cancer=sum(analysis_data$disease_group=="Cancer patient",na.rm=TRUE),metadata_source=m$source_file)
age_summary<-analysis_data |> dplyr::group_by(disease_group) |> dplyr::summarise(n_total=dplyr::n(),n_valid_age=sum(!is.na(age_for_model)),mean_age=mean(age_for_model,na.rm=TRUE),sd_age=sd(age_for_model,na.rm=TRUE),median_age=median(age_for_model,na.rm=TRUE),.groups="drop")
readr::write_csv(analysis_data,file.path(out,"SDY2583_CP25_analysis_data_with_metadata_RECONSTRUCTED.csv")); readr::write_csv(summary,file.path(out,"SDY2583_CP25_metadata_merge_summary_RECONSTRUCTED.csv")); readr::write_csv(age_summary,file.path(age,"SDY2583_CP25_age_QC_summary_RECONSTRUCTED.csv")); save(analysis_data,metadata,summary,age_summary,file=file.path(r,"SDY2583_CP25_STEP3A_metadata_merge_age_QC_RECONSTRUCTED.RData")); print(summary)
